/**
 * The tray icon, matching src-tauri/resources/tray_*.png (generated by
 * scripts/meetscribe/make_icons.py); uses currentColor like a macOS template image.
 */
type TrayIconState = "idle" | "recording" | "transcribing";

/** Two overlapping speech bubbles; the front one cuts a gap into the back one. */
const Bubbles = ({ maskId }: { maskId: string }) => (
  <>
    <mask id={maskId}>
      <rect width="64" height="64" fill="#fff" />
      <rect x="3" y="19" width="44" height="35" rx="11" fill="#000" />
      <path d="M8 44 L28 44 L6 63 Z" fill="#000" />
    </mask>
    <g mask={`url(#${maskId})`}>
      <rect
        x="24.5"
        y="8.5"
        width="33"
        height="24"
        rx="8"
        fill="none"
        stroke="currentColor"
        strokeWidth="5"
      />
      <path d="M43 33 L53 33 L55 42 Z" />
    </g>
    <rect
      x="8.5"
      y="24.5"
      width="33"
      height="24"
      rx="8"
      fill="none"
      stroke="currentColor"
      strokeWidth="5"
    />
    <path d="M12 49 L23 49 L10 59 Z" />
  </>
);

const RECORDING_BARS: [number, number][] = [
  [17, 12],
  [24.5, 24],
  [32, 34],
  [39.5, 24],
  [47, 12],
];

const TRANSCRIBING_LINES: [number, number][] = [
  [19, 34],
  [29.25, 28],
  [39.5, 19],
];

const Disc = ({
  maskId,
  children,
}: {
  maskId: string;
  children: React.ReactNode;
}) => (
  <>
    <mask id={maskId}>
      <rect width="64" height="64" fill="#fff" />
      {children}
    </mask>
    <circle cx="32" cy="32" r="31" mask={`url(#${maskId})`} />
  </>
);

const CONTENT: Record<TrayIconState, React.ReactNode> = {
  idle: <Bubbles maskId="tray-icon-idle-gap" />,
  recording: (
    <Disc maskId="tray-icon-recording-cut">
      {RECORDING_BARS.map(([x, h]) => (
        <rect
          key={x}
          x={x - 2.5}
          y={32 - h / 2}
          width="5"
          height={h}
          rx="2.5"
          fill="#000"
        />
      ))}
    </Disc>
  ),
  transcribing: (
    <Disc maskId="tray-icon-transcribing-cut">
      {TRANSCRIBING_LINES.map(([y, w]) => (
        <rect
          key={y}
          x="15"
          y={y}
          width={w}
          height="5.5"
          rx="2.75"
          fill="#000"
        />
      ))}
    </Disc>
  ),
};

const TrayIcon = ({
  state,
  size,
}: {
  state: TrayIconState;
  size: number | string;
}) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 64 64"
    className="fill-current"
    xmlns="http://www.w3.org/2000/svg"
  >
    {CONTENT[state]}
  </svg>
);

export default TrayIcon;
